import { Command } from 'commander';
import ora from 'ora';
import WebSocket from 'ws';

let socket: WebSocket | null = null;

export function registerPair(program: Command) {
  const pair = program.command('pair').description('Pair programming mode');

  pair
    .command('start <url>')
    .description('Start sharing terminal context')
    .action(async url => {
      const spinner = ora('Connecting to pair session...').start();
      socket = new WebSocket(url);
      socket.on('open', () => spinner.succeed('Pair session started.'));
      socket.on('message', data => console.log('PAIR:', data.toString()));
      socket.on('close', () => console.log('Pair session closed.'));
    });

  pair
    .command('stop')
    .description('Stop pair programming mode')
    .action(() => {
      if (socket) {
        socket.close();
        socket = null;
        console.log('Stopped pair session.');
      } else {
        console.log('No active pair session.');
      }
    });
}
